class RecurringCommitment {
  RecurringCommitment({
    required this.id,
    required this.name,
    required this.amount,
    required this.frequency,
    required this.firstDueMonth,
    DateTime? initialEffectiveMonth,
    List<CommitmentVersion>? history,
  }) : history = history ?? <CommitmentVersion>[] {
    if (this.history.isEmpty) {
      this.history.add(CommitmentVersion(
            effectiveMonth: initialEffectiveMonth ?? DateTime(2026, 1),
            name: name,
            amount: amount,
            frequency: frequency,
            firstDueMonth: firstDueMonth,
          ));
    }
  }

  final String id;
  String name;
  double amount;
  CommitmentFrequency frequency;
  int firstDueMonth;
  final List<CommitmentVersion> history;
}

class CommitmentVersion {
  const CommitmentVersion({
    required this.effectiveMonth,
    required this.name,
    required this.amount,
    required this.frequency,
    required this.firstDueMonth,
  });

  final DateTime effectiveMonth;
  final String name;
  final double amount;
  final CommitmentFrequency frequency;
  final int firstDueMonth;
}

class FacilityCostVersion {
  FacilityCostVersion({
    required this.id,
    required this.effectiveMonth,
    required this.recordedAt,
    required this.installmentAmount,
    required this.extraInstallmentPayment,
    required this.maintenanceFee,
    required this.insuranceFee,
    required this.insuranceFrequency,
    required this.insuranceDueMonth,
    this.initial = false,
  });

  final String id;
  final DateTime effectiveMonth;
  final DateTime recordedAt;
  final double installmentAmount;
  final double extraInstallmentPayment;
  final double maintenanceFee;
  final double insuranceFee;
  final InsuranceFrequency insuranceFrequency;
  final int insuranceDueMonth;
  final bool initial;

  double get monthlyRecurringTotal =>
      installmentAmount + extraInstallmentPayment + maintenanceFee;
}

