    facility.extraCommitments.add(
      RecurringCommitment(
        id: 'commitment_${facility.id}_${facility.extraCommitments.length + 1}',
        name: name.trim(),
        amount: amount,
        frequency: frequency,
        firstDueMonth: firstDueMonth,
        initialEffectiveMonth: currentMonth,
      ),
    );
