class AnimatedTabIndexedStack extends StatefulWidget {
  const AnimatedTabIndexedStack({
    required this.index,
    required this.children,
    super.key,
  });

  final int index;
  final List<Widget> children;

  @override
  State<AnimatedTabIndexedStack> createState() =>
      _AnimatedTabIndexedStackState();
}

class _AnimatedTabIndexedStackState extends State<AnimatedTabIndexedStack>
    with SingleTickerProviderStateMixin {
  late final AnimationController controller;
  late int currentIndex;
  late int previousIndex;
  int direction = 1;

  @override
  void initState() {
    super.initState();
    currentIndex = widget.index;
    previousIndex = widget.index;
    controller = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 260),
    )..value = 1;
  }

  @override
  void didUpdateWidget(covariant AnimatedTabIndexedStack oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.index == currentIndex) return;
    previousIndex = currentIndex;
    direction = widget.index > currentIndex ? 1 : -1;
    currentIndex = widget.index;
    controller.forward(from: 0);
  }

  @override
  void dispose() {
    controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final curved = CurvedAnimation(
      parent: controller,
      curve: Curves.easeOutCubic,
      reverseCurve: Curves.easeInCubic,
    );
    return Stack(
      fit: StackFit.expand,
      children: List.generate(widget.children.length, (index) {
        final child = KeyedSubtree(
          key: ValueKey('tab_$index'),
          child: widget.children[index],
        );
        if (index == currentIndex) {
          return SlideTransition(
            position: Tween<Offset>(
              begin: Offset(0.045 * direction, 0),
              end: Offset.zero,
            ).animate(curved),
            child: FadeTransition(
              opacity: Tween<double>(begin: 0.0, end: 1.0).animate(curved),
              child: child,
            ),
          );
        }
        if (index == previousIndex && controller.value < 1) {
          return IgnorePointer(
            child: SlideTransition(
              position: Tween<Offset>(
                begin: Offset.zero,
                end: Offset(-0.025 * direction, 0),
              ).animate(curved),
              child: FadeTransition(
                opacity: Tween<double>(begin: 1.0, end: 0.0).animate(curved),
                child: child,
              ),
            ),
          );
        }
        return Offstage(
          offstage: true,
          child: TickerMode(enabled: false, child: child),
        );
      }),
    );
  }
}

class NotificationBellIcon extends StatefulWidget {
  const NotificationBellIcon({required this.unreadCount, super.key});

  final int unreadCount;

  @override
  State<NotificationBellIcon> createState() => _NotificationBellIconState();
}

class _NotificationBellIconState extends State<NotificationBellIcon>
    with SingleTickerProviderStateMixin {
  late final AnimationController controller;
  late final Animation<double> turns;

  @override
  void initState() {
    super.initState();
    controller = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 760),
    );
    turns = TweenSequence<double>([
      TweenSequenceItem(tween: Tween(begin: 0, end: -0.055), weight: 1),
      TweenSequenceItem(tween: Tween(begin: -0.055, end: 0.055), weight: 2),
      TweenSequenceItem(tween: Tween(begin: 0.055, end: -0.045), weight: 2),
      TweenSequenceItem(tween: Tween(begin: -0.045, end: 0.035), weight: 2),
      TweenSequenceItem(tween: Tween(begin: 0.035, end: 0), weight: 1),
    ]).animate(CurvedAnimation(parent: controller, curve: Curves.easeInOut));
    if (widget.unreadCount > 0) controller.repeat();
  }

  @override
  void didUpdateWidget(covariant NotificationBellIcon oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.unreadCount > 0 && !controller.isAnimating) {
      controller.repeat();
    }
    if (widget.unreadCount == 0 && controller.isAnimating) {
      controller.stop();
      controller.value = 0;
    }
  }

  @override
  void dispose() {
    controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final bell = RotationTransition(
      turns: widget.unreadCount > 0
          ? turns
          : const AlwaysStoppedAnimation<double>(0),
      child: Icon(
        widget.unreadCount > 0
            ? Icons.notifications_active_rounded
            : Icons.notifications_outlined,
      ),
    );
    if (widget.unreadCount == 0) return bell;
    return Badge(
      label: Text('${widget.unreadCount}'),
      child: bell,
    );
  }
}

class _OwnerHomeScreenState extends State<OwnerHomeScreen> {
  int selectedIndex = 2;
  bool autoTourScheduled = false;
  int? tourIndex;
  bool recordTourResult = false;

  static const pages = [
    FacilitiesTab(),
    AdvancedReviewTab(),
    OwnerReportTab(),
    OwnerRequestsFeedTab(),
    OwnerAccountTab(),
  ];

  GlobalKey? _tourTarget(ContextualGuidedTourStep step) {
    final targets = <String, GlobalKey>{
      'owner_billing': ownerBillingTourTarget,
      'owner_add_tenant': ownerAddTenantTourTarget,
      'owner_billing_configuration': ownerBillingConfigurationTourTarget,
      'owner_properties_nav': ownerPropertiesNavTourTarget,
      'owner_payments_nav': ownerPaymentsNavTourTarget,
      'owner_home_nav': ownerHomeNavTourTarget,
      'owner_profile_nav': ownerProfileNavTourTarget,
      'owner_replay_tour': ownerReplayTourTarget,
    };
    final primary = targets[step.targetId];
    if (primary?.currentContext != null) return primary;
    return targets[step.fallbackTargetId] ?? primary;
  }

  void _startTour({required bool recordResult}) {
    final first = ownerContextualTourSteps.first;
    setState(() {
      this.recordTourResult = recordResult;
      tourIndex = 0;
      selectedIndex = first.tabIndex;
    });
  }

  void _moveTour(int direction) {
    final current = tourIndex;
    if (current == null) return;
    final next = current + direction;
    if (next >= ownerContextualTourSteps.length) {
      _finishTour(GuidedTourResult.completed);
      return;
    }
    if (next < 0) return;
    setState(() {
      tourIndex = next;
      selectedIndex = ownerContextualTourSteps[next].tabIndex;
    });
  }

  void _finishTour(GuidedTourResult result) {
    final shouldRecord = recordTourResult;
    setState(() {
      tourIndex = null;
      recordTourResult = false;
    });
    if (shouldRecord) {
      unawaited(RentalStoreScope.of(context).markGuidedTourSeen(
        audience: GuidedTourAudience.owner,
        result: result,
      ));
    }
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (autoTourScheduled) return;
    final store = RentalStoreScope.of(context);
    if (!store.shouldAutoShowGuidedTour(GuidedTourAudience.owner)) return;
    autoTourScheduled = true;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      _startTour(recordResult: true);
    });
  }

  @override
  Widget build(BuildContext context) {
    final store = RentalStoreScope.of(context);
    final titles = [
      tr(context, 'Properties'),
      tr(context, 'Payments'),
      tr(context, 'Home'),
      tr(context, 'Requests'),
      tr(context, 'Profile'),
    ];
    final title = selectedIndex == 2
        ? '${tr(context, timeGreeting(DateTime.now()))}, ${firstName(store.currentUser!.name)}'
        : titles[selectedIndex];
    final activeTourStep =
        tourIndex == null ? null : ownerContextualTourSteps[tourIndex!];
    return NotificationListener<GuidedTourRequestNotification>(
      onNotification: (notification) {
        if (notification.audience != GuidedTourAudience.owner) return false;
        _startTour(recordResult: false);
        return true;
      },
      child: Stack(
        children: [
          Scaffold(
            appBar: AppBar(
              backgroundColor: selectedIndex == 2 ? Colors.white : oceanCanvas,
              foregroundColor: oceanText,
              leadingWidth: 44,
              leading: const Padding(
                padding: EdgeInsets.only(left: 10),
                child: HomeOpsMark(size: 30, fillArtwork: true),
              ),
              title: Text(title),
              actions: [
                IconButton(
                  tooltip: tr(context, 'Notifications'),
                  onPressed: () => showNotifications(context),
                  icon: NotificationBellIcon(
                    unreadCount: store.unreadNotificationCount,
                  ),
                ),
                IconButton(
                  tooltip: tr(context, 'Log out'),
                  onPressed: () => confirmLogout(context),
                  icon: const Icon(Icons.logout_rounded),
                ),
              ],
            ),
            body: Column(
              children: [
                if (store.isReadOnlyObserver)
                  Container(
                    width: double.infinity,
                    padding:
                        const EdgeInsets.symmetric(horizontal: 16, vertical: 9),
                    color: const Color(0xFFFFF3CD),
                    child: const Row(
                      children: [
                        Icon(Icons.visibility_rounded, size: 19),
                        SizedBox(width: 8),
                        Expanded(
                          child: Text(
                            'Shareholder observer • View-only access. Changes are disabled.',
                            style: TextStyle(fontWeight: FontWeight.w700),
                          ),
                        ),
                      ],
                    ),
                  ),
                Expanded(
                  child: AnimatedTabIndexedStack(
                    index: selectedIndex,
                    children: pages,
                  ),
                ),
              ],
            ),
            bottomNavigationBar: SafeArea(
              top: false,
              child: AppBottomNavigator(
                selectedIndex: selectedIndex,
                onSelected: (index) {
                  if (index == selectedIndex) return;
                  setState(() {
                    selectedIndex = index;
                  });
                },
                items: [
                  AppBottomNavItem(
                    tourKey: ownerPropertiesNavTourTarget,
                    icon: Icons.apartment_outlined,
                    activeIcon: Icons.apartment_rounded,
                    label: tr(context, 'Properties'),
                  ),
                  AppBottomNavItem(
                    tourKey: ownerPaymentsNavTourTarget,
                    icon: Icons.payments_outlined,
                    activeIcon: Icons.payments_rounded,
                    label: tr(context, 'Payments'),
                  ),
                  AppBottomNavItem(
                    tourKey: ownerHomeNavTourTarget,
                    icon: Icons.home_outlined,
                    activeIcon: Icons.home_rounded,
                    label: tr(context, 'Home'),
                    prominent: true,
                  ),
                  AppBottomNavItem(
                    icon: Icons.bolt_outlined,
                    activeIcon: Icons.bolt_rounded,
                    label: tr(context, 'Requests'),
                  ),
                  AppBottomNavItem(
                    tourKey: ownerProfileNavTourTarget,
                    icon: Icons.person_outline_rounded,
                    activeIcon: Icons.person_rounded,
                    label: tr(context, 'Profile'),
                  ),
                ],
              ),
            ),
          ),
          if (activeTourStep != null)
            Positioned.fill(
              child: ContextualGuidedTourOverlay(
                audience: GuidedTourAudience.owner,
                step: activeTourStep,
                stepIndex: tourIndex!,
                totalSteps: ownerContextualTourSteps.length,
                targetKey: _tourTarget(activeTourStep),
                onNext: () => _moveTour(1),
                onBack: tourIndex == 0 ? null : () => _moveTour(-1),
                onSkip: () => _finishTour(GuidedTourResult.skipped),
              ),
            ),
        ],
      ),
    );
  }
}

