            if (!showPayAction) ...[
              const SizedBox(height: 12),
              Wrap(
                spacing: 8,
                runSpacing: 8,
                children: [
                  OutlinedButton.icon(
                    onPressed: () => openTenantIssuedInvoicePdf(context, bill),
                    icon: const Icon(Icons.picture_as_pdf_rounded),
