                      );
                      if (!twoColumns) {
                        return Column(
                          children: [
                            newField,
                            const SizedBox(height: 10),
                            confirmField,
                          ],
                        );
                      }
                      return Row(
                        children: [
                          Expanded(child: newField),
                          const SizedBox(width: 10),
                          Expanded(child: confirmField),
