    builder: (dialogContext) => AlertDialog(
      title: const Text('Add One-time Expense'),
      content: SizedBox(
        width: 480,
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            ProfileInfoRow(label: 'Facility', value: facility.name),
            ProfileInfoRow(
              label: 'Month',
              value: '${monthLabel(store.currentMonth)} • current month only',
            ),
            AppTextField(
              controller: category,
              label: 'Expense Category',
              hintText: 'e.g. Repair, bank fee, one-off service',
            ),
            AppTextField(
              controller: amount,
              label: 'Amount',
              prefixText: 'RM ',
              hintText: '0.00',
            ),
            AppTextField(
              controller: note,
              label: 'Note',
              hintText: 'Optional note for this expense',
            ),
          ],
        ),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(dialogContext),
          child: const Text('Cancel'),
        ),
        FilledButton.icon(
          onPressed: () async {
            if (category.text.trim().isEmpty) {
              showValidationMessage(
                dialogContext,
                'Expense category is required.',
              );
              return;
            }
            if (!isValidMoneyInput(amount.text, allowZero: false)) {
              showValidationMessage(
                dialogContext,
                'Expense amount must be a valid amount above RM 0.00.',
              );
              return;
            }
            final confirmed = await showActionConfirmation(
              dialogContext,
              title: 'Add this expense?',
              message:
                  '${category.text.trim()} of ${money(parseMoney(amount.text))} will be recorded for ${monthLabel(store.currentMonth)}.',
              confirmLabel: 'Add Expense',
            );
            if (!confirmed || !dialogContext.mounted) return;
            store.addAdditionalExpense(
              facility: facility,
              category: category.text,
              amount: parseMoney(amount.text),
              note: note.text,
            );
            Navigator.pop(dialogContext);
          },
          icon: const Icon(Icons.add_rounded),
          label: const Text('Review & Add'),
        ),
      ],
    ),
  );
}

void showNotifications(BuildContext context) {
  Navigator.of(context).push<void>(
    MaterialPageRoute<void>(builder: (_) => const NotificationsScreen()),
  );
}

class NotificationsScreen extends StatelessWidget {
  const NotificationsScreen({super.key});

  @override
  Widget build(BuildContext context) {
    final store = RentalStoreScope.of(context);
    return Scaffold(
      backgroundColor: oceanCanvas,
      appBar: AppBar(title: Text(tr(context, 'Notifications'))),
      body: AnimatedBuilder(
        animation: store,
        builder: (context, _) {
          final unread = store.unreadNotificationCount;
          final grouped = <String, List<AppNotification>>{};
          for (final notification in store.notifications) {
            final category = notificationCategoryFor(notification.message);
            grouped.putIfAbsent(category, () => []).add(notification);
          }
          const categoryOrder = [
            'Bill review',
            'Payment proof',
            'Tenant related',
            'Property changes',
            'Profile & settings',
            'Utility reading',
            'Requests',
            'System',
          ];
          final categories = [
            ...categoryOrder.where(grouped.containsKey),
            ...grouped.keys.where((item) => !categoryOrder.contains(item)),
          ];
          return Center(
            child: ConstrainedBox(
              constraints: const BoxConstraints(maxWidth: 820),
              child: ListView(
                key: const Key('notifications_full_page'),
                padding: const EdgeInsets.fromLTRB(16, 12, 16, 32),
                children: [
                  if (store.notifications.isNotEmpty)
                    Card(
                      child: CheckboxListTile(
                        contentPadding:
                            const EdgeInsets.symmetric(horizontal: 12),
                        value: unread == 0,
                        controlAffinity: ListTileControlAffinity.leading,
                        title: const Text(
                          'Mark all as read',
                          style: TextStyle(fontWeight: FontWeight.w700),
                        ),
                        subtitle: Text(
                          unread == 0
                              ? 'All notifications have been read'
                              : '$unread unread notification${unread == 1 ? '' : 's'}',
                        ),
                        onChanged: unread == 0
                            ? null
                            : (_) => store.markAllNotificationsRead(),
                      ),
                    ),
                  if (store.notifications.isEmpty)
                    const Card(
                      child: ListTile(title: Text('No notifications yet')),
                    ),
                  for (final category in categories) ...[
                    _NotificationCategoryHeader(
                      category: category,
                      notifications: grouped[category]!,
                    ),
                    Card(
                      child: Column(
                        children: [
                          for (final entry in grouped[category]!.indexed) ...[
                            _NotificationTile(
                              notification: entry.$2,
                              onTap: () => store.markNotificationRead(entry.$2),
                            ),
                            if (entry.$1 != grouped[category]!.length - 1)
                              const Divider(height: 1, indent: 50),
                          ],
                        ],
                      ),
                    ),
                  ],
                ],
              ),
            ),
          );
        },
      ),
    );
  }
}

