Widget appFieldLabel(String text, {Color? color}) {
  final trimmed = text.trimRight();
  final required = trimmed.endsWith('*');
  final labelText =
      required ? trimmed.substring(0, trimmed.length - 1).trimRight() : trimmed;
  return Text.rich(
    TextSpan(
      children: [
        TextSpan(text: labelText, style: TextStyle(color: color)),
        if (required)
          const TextSpan(
            text: ' *',
            style: TextStyle(color: Color(0xFFC43D4B)),
          ),
      ],
    ),
  );
}

class AppTextField extends StatelessWidget {
  const AppTextField({
    required this.controller,
    required this.label,
    this.helperText,
    this.errorText,
    this.hintText,
    this.prefixText,
    this.suffixText,
    this.keyboardType,
    this.onChanged,
    this.onTap,
    this.suffixIcon,
    this.readOnly = false,
    this.obscureText = false,
    this.inputFormatters,
    this.labelColor,
    super.key,
  });

  final TextEditingController controller;
  final String label;
  final String? helperText;
  final String? errorText;
  final String? hintText;
  final String? prefixText;
  final String? suffixText;
  final TextInputType? keyboardType;
  final ValueChanged<String>? onChanged;
  final VoidCallback? onTap;
  final Widget? suffixIcon;
  final bool readOnly;
  final bool obscureText;
  final List<TextInputFormatter>? inputFormatters;
  final Color? labelColor;

  @override
  Widget build(BuildContext context) {
    final resolvedKeyboardType = keyboardType ?? _keyboardTypeFor(label);
    final resolvedFormatters = inputFormatters ?? _formattersFor(label);
    final resolvedHintText =
        hintText?.trim().startsWith('Example:') == true ? null : hintText;
    final resolvedHelperText =
        helperText?.trim().startsWith('Example:') == true ? null : helperText;
    return Padding(
      padding: const EdgeInsets.only(bottom: 10),
      child: Focus(
        onFocusChange: (hasFocus) {
          if (!hasFocus || readOnly || !_isMoneyLabel(label.toLowerCase())) {
            return;
          }
          WidgetsBinding.instance.addPostFrameCallback((_) {
            if (!controller.selection.isValid) return;
            controller.selection = TextSelection(
              baseOffset: 0,
              extentOffset: controller.text.length,
            );
          });
        },
        child: TextField(
          controller: controller,
          scrollPadding: EdgeInsets.only(
            bottom: MediaQuery.viewInsetsOf(context).bottom + 120,
          ),
          readOnly: readOnly,
          obscureText: obscureText,
          keyboardType: resolvedKeyboardType,
          inputFormatters: resolvedFormatters,
          onChanged: onChanged,
          onTap: onTap,
          style: const TextStyle(fontSize: 14, height: 1.25),
          textAlignVertical: TextAlignVertical.center,
          decoration: InputDecoration(
            border: const OutlineInputBorder(),
            label: appFieldLabel(label, color: labelColor),
            hintText: resolvedHintText,
            helperText: resolvedHelperText,
            helperMaxLines: 3,
            errorText: errorText,
            errorMaxLines: 3,
            prefixText: prefixText,
            suffixText: suffixText,
            suffixIcon: suffixIcon,
          ),
        ),
      ),
    );
  }

  static TextInputType? _keyboardTypeFor(String label) {
    final normalized = label.toLowerCase();
    if (_isMoneyLabel(normalized) || normalized.contains('usage')) {
      return const TextInputType.numberWithOptions(decimal: true);
    }
    if (_isDateLabel(normalized)) return TextInputType.datetime;
    if (normalized.contains('phone') || normalized.contains('whatsapp')) {
      return TextInputType.phone;
    }
    if (normalized == 'email' || normalized.contains('email')) {
      return TextInputType.emailAddress;
    }
    return null;
  }

  static List<TextInputFormatter>? _formattersFor(String label) {
    final normalized = label.toLowerCase();
    if (_isDateLabel(normalized)) {
      return [FilteringTextInputFormatter.allow(RegExp(r'[0-9/]'))];
    }
    if (_isMoneyLabel(normalized) || normalized.contains('usage')) {
      if (normalized.contains('usage')) {
        return [FilteringTextInputFormatter.allow(RegExp(r'[0-9.]'))];
      }
      return [
        FilteringTextInputFormatter.allow(RegExp(r'[0-9.]')),
        TextInputFormatter.withFunction((oldValue, newValue) {
          final text = newValue.text;
          if ('.'.allMatches(text).length > 1) return oldValue;
          final decimalIndex = text.indexOf('.');
          if (decimalIndex >= 0 && text.length - decimalIndex - 1 > 2) {
            return oldValue;
          }
          final normalizedText = normalizeMoneyInputText(text);
          final removed = text.length - normalizedText.length;
          final cursor = math.max(
            0,
            math.min(
              normalizedText.length,
              newValue.selection.end - removed,
            ),
          );
          return TextEditingValue(
            text: normalizedText,
            selection: TextSelection.collapsed(offset: cursor),
          );
        }),
      ];
    }
    if (normalized.contains('phone') || normalized.contains('whatsapp')) {
      return [FilteringTextInputFormatter.allow(RegExp(r'[0-9+\-() ]'))];
    }
    if (_isHumanNameLabel(normalized)) {
      return [FilteringTextInputFormatter.deny(RegExp(r'[0-9]'))];
    }
    if (normalized == 'sex' || normalized == 'city' || normalized == 'state') {
      return [FilteringTextInputFormatter.deny(RegExp(r'[0-9]'))];
    }
    return null;
  }

  static bool _isDateLabel(String normalized) =>
      normalized.contains('date') ||
      normalized.contains('birth') ||
      normalized.contains('lease start') ||
      normalized.contains('lease end');

  static bool _isMoneyLabel(String normalized) =>
      normalized.contains('rent') ||
      normalized.contains('amount') ||
      normalized.contains('installment') ||
      normalized.contains('maintenance') ||
      normalized.contains('insurance') ||
      normalized.contains('charge') ||
      normalized.contains('premium') ||
      normalized.contains('payment');

  static bool _isHumanNameLabel(String normalized) =>
      normalized == 'full name' ||
      normalized == 'full name *' ||
      normalized == 'tenant' ||
      normalized == 'beneficiary';
}

class ResponsiveFormPair extends StatelessWidget {
  const ResponsiveFormPair({
    required this.first,
    required this.second,
    this.gap = 10,
    this.breakpoint = 420,
    super.key,
  });

  final Widget first;
  final Widget second;
  final double gap;
  final double breakpoint;

  @override
  Widget build(BuildContext context) => LayoutBuilder(
        builder: (context, constraints) {
          if (constraints.maxWidth < breakpoint) {
            return Column(
              children: [first, SizedBox(height: gap), second],
            );
          }
          return Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Expanded(child: first),
              SizedBox(width: gap),
              Expanded(child: second),
            ],
          );
        },
      );
}

class AppDatePickerField extends StatelessWidget {
  const AppDatePickerField({
    required this.controller,
    required this.label,
    required this.firstDate,
    required this.lastDate,
    this.initialDate,
    this.errorText,
    this.onSelected,
    this.showFormatHint = true,
    super.key,
  });

  final TextEditingController controller;
  final String label;
  final DateTime firstDate;
  final DateTime lastDate;
  final DateTime? initialDate;
  final String? errorText;
  final ValueChanged<DateTime>? onSelected;
  final bool showFormatHint;

  @override
  Widget build(BuildContext context) {
    return AppTextField(
      controller: controller,
      label: label,
      helperText: showFormatHint ? 'DD/MM/YYYY' : null,
      errorText: errorText,
      readOnly: true,
      suffixIcon: const Icon(Icons.calendar_month_rounded),
      onTap: () async {
        final parsed = parseDateInput(controller.text);
        var resolvedInitial = parsed ?? initialDate ?? DateTime.now();
        if (resolvedInitial.isBefore(firstDate)) resolvedInitial = firstDate;
        if (resolvedInitial.isAfter(lastDate)) resolvedInitial = lastDate;
        final selected = await showDatePicker(
          context: context,
          initialDate: resolvedInitial,
          firstDate: firstDate,
          lastDate: lastDate,
          helpText: label,
        );
        if (selected == null) return;
        controller.text = dateLabel(selected);
        onSelected?.call(selected);
      },
    );
  }
}

